import { ChangeDetectionStrategy, Component, input } from '@angular/core';
import type { LlmProvenance } from '@vsf/contracts';

/** "Generated by <model> · prompt <ref>" with a Mock badge when no real LLM was called. */
@Component({
  selector: 'app-llm-provenance',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (llm(); as l) {
      <span class="provenance" data-testid="llm-provenance">
        Generated by <span class="mono">{{ l.model }}</span> · prompt <span class="mono">{{ l.promptRef }}</span>
        @if (l.mock) {
          <span class="chip chip-mock" data-testid="mock-badge">Mock</span>
        }
      </span>
    } @else {
      <span class="provenance">Human authored</span>
    }
  `,
  styles: `
    .provenance {
      display: inline-flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 4px;
      font: var(--mat-sys-body-small);
      color: var(--mat-sys-on-surface-variant);
    }
    .mono {
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    }
  `,
})
export class LlmProvenanceView {
  readonly llm = input<LlmProvenance | null>(null);
}
